/** Process exit code for runtime failures: missing todo, unreadable or corrupted storage. */
export const EXIT_FAILURE = 1;

/** Process exit code for bad invocations: unknown command, missing or malformed arguments. */
export const EXIT_USAGE = 2;

/**
 * Base class for errors the CLI expects and reports as a one-line message.
 * Anything that is not a TodoError is treated as a bug.
 */
export class TodoError extends Error {
  /**
   * @param {string} message
   * @param {{ exitCode?: number, cause?: unknown }} [options]
   */
  constructor(message, { exitCode = EXIT_FAILURE, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = new.target.name;
    this.exitCode = exitCode;
  }
}

/** The command line was malformed: wrong command, missing or invalid argument. */
export class UsageError extends TodoError {
  /** @param {string} message */
  constructor(message) {
    super(message, { exitCode: EXIT_USAGE });
  }
}

/** No todo exists with the requested id. */
export class NotFoundError extends TodoError {
  /** @param {number} id */
  constructor(id) {
    super(`Todo #${id} not found. Run "node index.js list" to see existing ids.`);
    this.id = id;
  }
}

/** todos.json could not be read, parsed, validated, locked, or written. */
export class StorageError extends TodoError {
  /**
   * @param {string} message
   * @param {{ cause?: unknown }} [options]
   */
  constructor(message, { cause } = {}) {
    super(message, { exitCode: EXIT_FAILURE, cause });
  }
}

