import fs from 'node:fs';
import path from 'node:path';
import { randomBytes } from 'node:crypto';
import { StorageError } from './errors.js';

/** @typedef {import('./todos.js').Todo} Todo */

/** Name of the data file created in the working directory. */
export const TODOS_FILENAME = 'todos.json';

/**
 * @typedef {object} LockOptions
 * @property {number} [timeoutMs] Give up acquiring the lock after this long.
 * @property {number} [staleMs] Treat a lock file older than this as abandoned by a crashed process.
 * @property {number} [retryMs] Pause between acquisition attempts.
 */

/** @type {Required<LockOptions>} */
export const DEFAULT_LOCK_OPTIONS = Object.freeze({
  timeoutMs: 5000,
  staleMs: 10_000,
  retryMs: 20,
});

const sleepCell = new Int32Array(new SharedArrayBuffer(4));

/** @param {number} ms */
function sleepSync(ms) {
  Atomics.wait(sleepCell, 0, 0, ms);
}

/**
 * File-backed todo storage.
 *
 * Writes go to a temporary file that is renamed over todos.json, so readers
 * never see a half-written file. `update` holds an exclusive lock file for the
 * whole read-modify-write cycle so concurrent CLI invocations don't lose each
 * other's changes.
 *
 * @param {string} filePath Path to the JSON data file.
 * @param {{ lock?: LockOptions }} [options]
 */
export function createStore(filePath, { lock = {} } = {}) {
  const lockPath = `${filePath}.lock`;
  const lockOptions = { ...DEFAULT_LOCK_OPTIONS, ...lock };

  /**
   * Read and validate the todo list. A missing or blank file is an empty list.
   * @returns {Todo[]}
   * @throws {StorageError} when the file is unreadable, not JSON, or has the wrong shape.
   */
  function load() {
    let raw;
    try {
      raw = fs.readFileSync(filePath, 'utf8');
    } catch (error) {
      if (error.code === 'ENOENT') {
        return [];
      }
      throw new StorageError(`Could not read ${filePath}: ${error.message}`, { cause: error });
    }
    if (raw.trim() === '') {
      return [];
    }
    let data;
    try {
      data = JSON.parse(raw);
    } catch (error) {
      throw new StorageError(
        `${filePath} is not valid JSON (${error.message}). Fix the file or move it aside to start a new list.`,
        { cause: error },
      );
    }
    validateTodos(data, filePath);
    return data;
  }

  /**
   * Replace the file contents atomically.
   * @param {readonly Todo[]} todos
   * @throws {StorageError}
   */
  function save(todos) {
    const tempPath = `${filePath}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`;
    try {
      fs.writeFileSync(tempPath, `${JSON.stringify(todos, null, 2)}\n`, { encoding: 'utf8', flush: true });
      fs.renameSync(tempPath, filePath);
    } catch (error) {
      fs.rmSync(tempPath, { force: true });
      throw new StorageError(`Could not write ${filePath}: ${error.message}`, { cause: error });
    }
  }

  /**
   * Run a read-modify-write cycle under the lock. The mutator receives the
   * current list and returns the next one plus a value to hand back to the
   * caller. Returning the same array skips the write.
   * @template T
   * @param {(todos: Todo[]) => { todos: readonly Todo[], value: T }} mutator
   * @returns {T}
   */
  function update(mutator) {
    const release = acquireLock(lockPath, lockOptions);
    try {
      const current = load();
      const { todos, value } = mutator(current);
      if (todos !== current) {
        save(todos);
      }
      return value;
    } finally {
      release();
    }
  }

  return { filePath, lockPath, load, save, update };
}

/**
 * Create the store for todos.json in a directory.
 * @param {string} directory
 * @param {{ lock?: LockOptions }} [options]
 */
export function createStoreInDirectory(directory, options) {
  return createStore(path.join(directory, TODOS_FILENAME), options);
}

/**
 * Take an exclusive lock by creating the lock file with O_EXCL.
 * @param {string} lockPath
 * @param {Required<LockOptions>} options
 * @returns {() => void} Releases the lock.
 * @throws {StorageError} on timeout or an unexpected file system error.
 */
export function acquireLock(lockPath, { timeoutMs, staleMs, retryMs }) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const fd = fs.openSync(lockPath, 'wx');
      fs.writeSync(fd, String(process.pid));
      fs.closeSync(fd);
      return () => fs.rmSync(lockPath, { force: true });
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw new StorageError(`Could not create lock file ${lockPath}: ${error.message}`, { cause: error });
      }
    }
    if (removeIfStale(lockPath, staleMs)) {
      continue;
    }
    if (Date.now() >= deadline) {
      throw new StorageError(
