import { EXIT_FAILURE, EXIT_USAGE, TodoError, UsageError } from './errors.js';
import { formatTodo, formatTodoList } from './format.js';
import { createStoreInDirectory } from './store.js';
import { addTodo, completeTodo, deleteTodo, parseId } from './todos.js';

/** Exit code for a successful command. */
export const EXIT_SUCCESS = 0;

/** Help text printed by `help` and after usage errors. */
export const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help

Todos are stored in todos.json in the current directory.`;

const HELP_ALIASES = new Set(['help', '--help', '-h']);

/**
 * @typedef {object} RunOptions
 * @property {string} [cwd] Directory holding todos.json. Defaults to process.cwd().
 * @property {{ write(chunk: string): unknown }} [stdout]
 * @property {{ write(chunk: string): unknown }} [stderr]
 * @property {() => Date} [now] Clock used for createdAt.
 * @property {import('./store.js').LockOptions} [lock]
 */

/**
 * Parse arguments, run one command, and report the outcome.
 * @param {readonly string[]} argv Arguments after `node index.js`.
 * @param {RunOptions} [options]
 * @returns {number} Process exit code.
 */
export function run(argv, options = {}) {
  const {
    cwd = process.cwd(),
    stdout = process.stdout,
    stderr = process.stderr,
    now = () => new Date(),
    lock,
  } = options;
  const out = (text) => stdout.write(`${text}\n`);
  const [command, ...args] = argv;

  if (command === undefined) {
    stderr.write(`${USAGE}\n`);
    return EXIT_USAGE;
  }
  if (HELP_ALIASES.has(command)) {
    out(USAGE);
    return EXIT_SUCCESS;
  }

  const handler = Object.hasOwn(COMMANDS, command) ? COMMANDS[command] : undefined;
  try {
    if (!handler) {
      throw new UsageError(`Unknown command "${command}".`);
    }
    const store = createStoreInDirectory(cwd, { lock });
    out(handler(args, { store, now }));
    return EXIT_SUCCESS;
  } catch (error) {
    if (error instanceof TodoError) {
      stderr.write(`Error: ${error.message}\n`);
      if (error instanceof UsageError && !handler) {
        stderr.write(`\n${USAGE}\n`);
      }
      return error.exitCode;
    }
    stderr.write(`Unexpected error: ${error?.stack ?? error}\n`);
    return EXIT_FAILURE;
  }
}

/**
 * @typedef {object} CommandContext
 * @property {ReturnType<typeof createStoreInDirectory>} store
 * @property {() => Date} now
 */

/** @type {Record<string, (args: string[], context: CommandContext) => string>} */
const COMMANDS = {
  add(args, { store, now }) {
    if (args.length === 0) {
      throw new UsageError('Missing todo text. Usage: node index.js add "<text>"');
    }
    // Unquoted words (`add Buy milk`) are joined, matching the quoted form.
    const text = args.join(' ');
    const todo = store.update((todos) => {
      const result = addTodo(todos, text, now());
      return { todos: result.todos, value: result.todo };
    });
    return `Added todo #${todo.id}: ${todo.text}`;
  },

  list(args, { store }) {
    expectArgs('list', args, 0);
    return formatTodoList(store.load());
  },

  complete(args, { store }) {
    const id = parseId(expectArgs('complete', args, 1));
    const { todo, alreadyCompleted } = store.update((todos) => {
      const result = completeTodo(todos, id);
      return { todos: result.todos, value: result };
    });
    return alreadyCompleted
      ? `Todo #${todo.id} is already done: ${todo.text}`
      : `Completed todo #${todo.id}: ${todo.text}\n${formatTodo(todo)}`;
  },

  delete(args, { store }) {
    const id = parseId(expectArgs('delete', args, 1));
    const todo = store.update((todos) => {
      const result = deleteTodo(todos, id);
      return { todos: result.todos, value: result.todo };
    });
    return `Deleted todo #${todo.id}: ${todo.text}`;
  },
};

/**
 * @param {string} command
 * @param {string[]} args
 * @param {0 | 1} count
 * @returns {string | undefined} The single argument when count is 1.
 */
function expectArgs(command, args, count) {
  if (count === 1 && args.length === 0) {
    throw new UsageError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > count) {
    const expected = count === 0 ? 'no arguments' : 'exactly one id';
    throw new UsageError(`"${command}" takes ${expected}, got ${args.length}.`);
  }
  return args[0];
}

