import { formatTodo, formatTodoList } from './format.js';
import { createStoreInDirectory } from './store.js';
import { addTodo, completeTodo, deleteTodo, parseId } from './todos.js';

/** Exit code for a successful command. */
export const EXIT_SUCCESS = 0;

/** Help text printed by `help` and after usage errors. */
export const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help

Todos are stored in todos.json in the current directory.`;

const HELP_ALIASES = new Set(['help', '--help', '-h']);

/**
 * @typedef {object} RunOptions
 * @property {string} [cwd] Directory holding todos.json. Defaults to process.cwd().
 * @property {{ write(chunk: string): unknown }} [stdout]
 * @property {{ write(chunk: string): unknown }} [stderr]
 * @property {() => Date} [now] Clock used for createdAt.
 * @property {import('./store.js').LockOptions} [lock]
 */

/**
 * Parse arguments, run one command, and report the outcome.
 * @param {readonly string[]} argv Arguments after `node index.js`.
 * @param {RunOptions} [options]
 * @returns {number} Process exit code.
 */
export function run(argv, options = {}) {
  const {
    cwd = process.cwd(),
    stdout = process.stdout,
    stderr = process.stderr,
    now = () => new Date(),
    lock,
  } = options;
  const out = (text) => stdout.write(`${text}\n`);
  const [command, ...args] = argv;

