import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { run } from '../../src/cli.js';

export const INDEX_PATH = path.resolve(import.meta.dirname, '../../index.js');

/**
 * Fresh temporary directory, removed when the test finishes.
 * @param {import('node:test').TestContext} t
 */
export function tempDir(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-test-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}

/** Run `node index.js ...args` as a child process with `cwd` as its working directory. */
export function runCli(args, { cwd }) {
  const result = spawnSync(process.execPath, [INDEX_PATH, ...args], { cwd, encoding: 'utf8', timeout: 10_000 });
  if (result.error) {
    throw result.error;
  }
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

/** Async variant of {@link runCli} so several processes can run at once. */
export function runCliAsync(args, { cwd }) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [INDEX_PATH, ...args], { cwd, timeout: 20_000 });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf8').on('data', (chunk) => { stdout += chunk; });
    child.stderr.setEncoding('utf8').on('data', (chunk) => { stderr += chunk; });
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
  });
}

/** Call `run` in-process with captured output streams. */
export function runInProcess(argv, options = {}) {
  const stdout = [];
  const stderr = [];
  const code = run(argv, {
    ...options,
    stdout: { write: (chunk) => stdout.push(chunk) },
    stderr: { write: (chunk) => stderr.push(chunk) },
  });
  return { code, stdout: stdout.join(''), stderr: stderr.join('') };
}

export function todosPath(dir) {
  return path.join(dir, 'todos.json');
}

export function readTodos(dir) {
  return JSON.parse(fs.readFileSync(todosPath(dir), 'utf8'));
}

export function writeTodosRaw(dir, contents) {
  fs.writeFileSync(todosPath(dir), contents, 'utf8');
}

export function writeTodos(dir, todos) {
  writeTodosRaw(dir, JSON.stringify(todos, null, 2));
}

/** Build a valid todo, overriding any fields. */
export function makeTodo(overrides = {}) {
  return {
    id: 1,
    text: 'Buy groceries',
    completed: false,
    createdAt: '2026-01-01T00:00:00.000Z',
    ...overrides,
  };
}

