import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { NotFoundError, UsageError } from '../src/errors.js';
import {
  MAX_TEXT_LENGTH,
  addTodo,
  completeTodo,
  deleteTodo,
  nextId,
  normalizeText,
  parseId,
} from '../src/todos.js';
import { makeTodo } from './helpers/cli.js';

const NOW = new Date('2026-09-30T12:00:00.000Z');

/** Frozen fixture: any attempt to mutate it throws in strict mode. */
function frozenList(...todos) {
  return Object.freeze(todos.map((todo) => Object.freeze(makeTodo(todo))));
}

describe('normalizeText', () => {
  it('returns text with surrounding whitespace trimmed', () => {
    assert.equal(normalizeText('  Buy groceries \t'), 'Buy groceries');
  });

  it('keeps internal spacing and unicode untouched', () => {
    assert.equal(normalizeText('Café  ☕ 日本語 🎉'), 'Café  ☕ 日本語 🎉');
  });

  for (const [label, input] of [
    ['empty string', ''],
    ['whitespace only', '   \t '],
    ['undefined', undefined],
    ['null', null],
    ['a number', 42],
  ]) {
    it(`rejects ${label}`, () => {
      assert.throws(() => normalizeText(input), { name: 'UsageError', message: /cannot be empty/ });
    });
  }

  for (const [label, input] of [
    ['a newline', 'first\nsecond'],
    ['a carriage return', 'first\rsecond'],
    ['a tab', 'first\tsecond'],
    ['an ANSI escape sequence', 'evil \u001b[2J clear'],
    ['a unicode line separator', 'first second'],
  ]) {
    it(`rejects text containing ${label}`, () => {
      assert.throws(() => normalizeText(input), { name: 'UsageError', message: /single line/ });
    });
  }

  it('accepts text exactly at the maximum length', () => {
    const text = 'a'.repeat(MAX_TEXT_LENGTH);
    assert.equal(normalizeText(text), text);
  });

  it('rejects text one character over the maximum length', () => {
    assert.throws(() => normalizeText('a'.repeat(MAX_TEXT_LENGTH + 1)), {
      name: 'UsageError',
      message: new RegExp(`${MAX_TEXT_LENGTH + 1} characters long; the maximum is ${MAX_TEXT_LENGTH}`),
    });
  });

  it('counts emoji as one character each, not as UTF-16 surrogate pairs', () => {
    const text = '😀'.repeat(MAX_TEXT_LENGTH);
    assert.equal(text.length, MAX_TEXT_LENGTH * 2);
    assert.equal(normalizeText(text), text);
  });
});

describe('parseId', () => {
  for (const [input, expected] of [['1', 1], ['42', 42], ['007', 7], [String(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER]]) {
    it(`parses "${input}" as ${expected}`, () => {
      assert.equal(parseId(input), expected);
    });
  }

  for (const input of ['0', '-1', '1.5', '1e3', 'abc', '', ' 1', '0x1F', '12abc', '99999999999999999999', undefined]) {
    it(`rejects ${JSON.stringify(input) ?? 'undefined'}`, () => {
      assert.throws(() => parseId(input), (error) => {
        assert.ok(error instanceof UsageError);
        assert.match(error.message, /Invalid todo id .* Expected a positive integer/);
        return true;
      });
    });
  }
});

describe('nextId', () => {
  it('starts at 1 for an empty list', () => {
    assert.equal(nextId([]), 1);
  });

  it('is one more than the highest id, even with gaps or unsorted ids', () => {
    assert.equal(nextId(frozenList({ id: 3 }, { id: 9 }, { id: 5 })), 10);
  });
});

describe('addTodo', () => {
  it('appends a pending todo with the next id and an ISO createdAt', () => {
    const { todos, todo } = addTodo(frozenList({ id: 1 }), '  Walk the dog ', NOW);
    assert.deepEqual(todo, { id: 2, text: 'Walk the dog', completed: false, createdAt: '2026-09-30T12:00:00.000Z' });
    assert.equal(todos.length, 2);
    assert.equal(todos[1], todo);
  });

  it('does not modify the input list', () => {
    const input = frozenList({ id: 1 });
    addTodo(input, 'Another', NOW);
    assert.equal(input.length, 1);
  });

  it('rejects invalid text without producing a todo', () => {
    assert.throws(() => addTodo([], '   ', NOW), UsageError);
  });
});

describe('completeTodo', () => {
  it('marks the matching todo done and leaves others alone', () => {
    const input = frozenList({ id: 1 }, { id: 2, text: 'Other' });
    const { todos, todo, alreadyCompleted } = completeTodo(input, 2);
    assert.equal(alreadyCompleted, false);
    assert.equal(todo.completed, true);
    assert.deepEqual(todos, [input[0], { ...input[1], completed: true }]);
    assert.equal(input[1].completed, false, 'input todo must not be mutated');
  });

  it('returns the same list when the todo is already done', () => {
    const input = frozenList({ id: 1, completed: true });
    const result = completeTodo(input, 1);
    assert.equal(result.alreadyCompleted, true);
    assert.equal(result.todos, input);
  });

  it('throws NotFoundError for an unknown id', () => {
    assert.throws(() => completeTodo(frozenList({ id: 1 }), 99), (error) => {
      assert.ok(error instanceof NotFoundError);
      assert.equal(error.id, 99);
      assert.match(error.message, /Todo #99 not found/);
      return true;
    });
  });

  it('throws NotFoundError on an empty list', () => {
    assert.throws(() => completeTodo([], 1), NotFoundError);
  });
});

describe('deleteTodo', () => {
  it('removes only the matching todo and returns it', () => {
    const input = frozenList({ id: 1 }, { id: 2 }, { id: 3 });
    const { todos, todo } = deleteTodo(input, 2);
    assert.equal(todo, input[1]);
    assert.deepEqual(todos.map((t) => t.id), [1, 3]);
    assert.equal(input.length, 3, 'input list must not be mutated');
  });

