import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { EMPTY_LIST_MESSAGE, formatTodo, formatTodoList } from '../src/format.js';
import { makeTodo } from './helpers/cli.js';

describe('formatTodo', () => {
  it('shows [ ] for a pending todo', () => {
    assert.equal(formatTodo(makeTodo({ id: 3, text: 'Buy groceries' })), '3. [ ] Buy groceries');
  });

  it('shows [x] for a completed todo', () => {
    assert.equal(formatTodo(makeTodo({ id: 12, text: 'Pay rent', completed: true })), '12. [x] Pay rent');
  });

  it('prints unicode text as-is', () => {
    assert.equal(formatTodo(makeTodo({ text: 'Café ☕ 日本語' })), '1. [ ] Café ☕ 日本語');
  });
});

describe('formatTodoList', () => {
  it('returns the empty-list message when there are no todos', () => {
    assert.equal(formatTodoList([]), EMPTY_LIST_MESSAGE);
  });

  it('lists every todo in order followed by a pending/done summary', () => {
    const output = formatTodoList([
      makeTodo({ id: 1, text: 'Buy groceries', completed: true }),
      makeTodo({ id: 2, text: 'Walk the dog' }),
      makeTodo({ id: 4, text: 'Call mom' }),
    ]);
    assert.equal(output, [
      '1. [x] Buy groceries',
      '2. [ ] Walk the dog',
      '4. [ ] Call mom',
      '',
      '3 todos: 2 pending, 1 done',
    ].join('\n'));
  });

  it('uses the singular noun for a single todo', () => {
    assert.match(formatTodoList([makeTodo()]), /^1 todo: 1 pending, 0 done$/m);
  });
});

