import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { describe, it } from 'node:test';
import { StorageError } from '../src/errors.js';
import {
  DEFAULT_LOCK_OPTIONS,
  TODOS_FILENAME,
  acquireLock,
  createStore,
  createStoreInDirectory,
  validateTodos,
} from '../src/store.js';
import { makeTodo, readTodos, tempDir, todosPath, writeTodos, writeTodosRaw } from './helpers/cli.js';

describe('store.load', () => {
  it('returns an empty list when todos.json does not exist', (t) => {
    const dir = tempDir(t);
    assert.deepEqual(createStoreInDirectory(dir).load(), []);
    assert.equal(fs.existsSync(todosPath(dir)), false, 'load must not create the file');
  });

  it('returns an empty list for a blank file', (t) => {
    const dir = tempDir(t);
    writeTodosRaw(dir, '  \n');
    assert.deepEqual(createStoreInDirectory(dir).load(), []);
  });

  it('keeps fields it does not know about', (t) => {
    const dir = tempDir(t);
    writeTodos(dir, [makeTodo({ priority: 'high' })]);
    assert.equal(createStoreInDirectory(dir).load()[0].priority, 'high');
  });

  it('throws StorageError naming the file when JSON is malformed', (t) => {
    const dir = tempDir(t);
    writeTodosRaw(dir, '[{"id": 1,');
    assert.throws(() => createStoreInDirectory(dir).load(), (error) => {
      assert.ok(error instanceof StorageError);
      assert.ok(error.message.includes(todosPath(dir)));
      assert.match(error.message, /not valid JSON/);
      assert.ok(error.cause instanceof SyntaxError);
      return true;
    });
  });

  it('throws StorageError when the path is a directory', (t) => {
    const dir = tempDir(t);
    fs.mkdirSync(todosPath(dir));
    assert.throws(() => createStoreInDirectory(dir).load(), { name: 'StorageError', message: /Could not read/ });
  });
});

describe('store.save', () => {
  it('round-trips through load as pretty JSON with a trailing newline', (t) => {
    const dir = tempDir(t);
    const store = createStoreInDirectory(dir);
    const todos = [makeTodo({ id: 1 }), makeTodo({ id: 2, completed: true })];
    store.save(todos);
    assert.deepEqual(store.load(), todos);
    const raw = fs.readFileSync(todosPath(dir), 'utf8');
    assert.equal(raw, `${JSON.stringify(todos, null, 2)}\n`);
  });

  it('leaves no temporary files behind', (t) => {
    const dir = tempDir(t);
    createStoreInDirectory(dir).save([makeTodo()]);
    assert.deepEqual(fs.readdirSync(dir), [TODOS_FILENAME]);
  });

  it('throws StorageError and cleans up when the directory does not exist', (t) => {
    const dir = tempDir(t);
    const store = createStore(path.join(dir, 'missing', TODOS_FILENAME));
    assert.throws(() => store.save([]), { name: 'StorageError', message: /Could not write/ });
    assert.deepEqual(fs.readdirSync(dir), []);
  });
});

describe('store.update', () => {
  it('saves the list returned by the mutator and returns its value', (t) => {
    const dir = tempDir(t);
    const store = createStoreInDirectory(dir);
    const value = store.update((todos) => ({ todos: [...todos, makeTodo()], value: 'added' }));
    assert.equal(value, 'added');
    assert.deepEqual(readTodos(dir), [makeTodo()]);
  });

  it('skips the write when the mutator returns the same array', (t) => {
    const dir = tempDir(t);
    createStoreInDirectory(dir).update((todos) => ({ todos, value: null }));
    assert.equal(fs.existsSync(todosPath(dir)), false);
  });

  it('releases the lock after a successful update', (t) => {
    const dir = tempDir(t);
    const store = createStoreInDirectory(dir);
    store.update((todos) => ({ todos: [makeTodo()], value: null }));
    assert.equal(fs.existsSync(store.lockPath), false);
  });

  it('releases the lock and writes nothing when the mutator throws', (t) => {
    const dir = tempDir(t);
    const store = createStoreInDirectory(dir);
    writeTodos(dir, [makeTodo()]);
    const before = fs.readFileSync(todosPath(dir), 'utf8');
    assert.throws(() => store.update(() => { throw new Error('boom'); }), /boom/);
    assert.equal(fs.existsSync(store.lockPath), false);
    assert.equal(fs.readFileSync(todosPath(dir), 'utf8'), before);
  });

  it('releases the lock when the file is corrupted', (t) => {
    const dir = tempDir(t);
    const store = createStoreInDirectory(dir);
    writeTodosRaw(dir, 'not json');
    assert.throws(() => store.update((todos) => ({ todos, value: null })), StorageError);
    assert.equal(fs.existsSync(store.lockPath), false);
  });
});

describe('acquireLock', () => {
  const fast = { ...DEFAULT_LOCK_OPTIONS, timeoutMs: 100, retryMs: 5 };

  it('creates the lock file and removes it on release', (t) => {
    const lockPath = path.join(tempDir(t), 'x.lock');
    const release = acquireLock(lockPath, fast);
    assert.equal(fs.readFileSync(lockPath, 'utf8'), String(process.pid));
    release();
    assert.equal(fs.existsSync(lockPath), false);
  });

  it('times out while another holder has a fresh lock', (t) => {
    const lockPath = path.join(tempDir(t), 'x.lock');
    const release = acquireLock(lockPath, fast);
    t.after(release);
    const started = Date.now();
    assert.throws(() => acquireLock(lockPath, fast), { name: 'StorageError', message: /Timed out after 100ms/ });
    assert.ok(Date.now() - started >= 100, 'should wait for the full timeout before giving up');
  });

  it('takes over a lock older than staleMs', (t) => {
    const lockPath = path.join(tempDir(t), 'x.lock');
    fs.writeFileSync(lockPath, '999999');
    const old = new Date(Date.now() - 60_000);
    fs.utimesSync(lockPath, old, old);
    const release = acquireLock(lockPath, { ...fast, staleMs: 1000 });
    assert.equal(fs.readFileSync(lockPath, 'utf8'), String(process.pid));
    release();
  });

  it('throws StorageError when the lock directory does not exist', (t) => {
    const lockPath = path.join(tempDir(t), 'missing', 'x.lock');
    assert.throws(() => acquireLock(lockPath, fast), { name: 'StorageError', message: /Could not create lock file/ });
  });
});

describe('validateTodos', () => {
  it('accepts an empty array and an array of valid todos', () => {
    assert.doesNotThrow(() => validateTodos([], 'todos.json'));
    assert.doesNotThrow(() => validateTodos([makeTodo({ id: 1 }), makeTodo({ id: 2 })], 'todos.json'));
  });

