    ['null', null, /found null/],
    ['a string', 'todos', /found "todos"/],
    ['a non-object item', [42], /index 0: expected an object, found number 42/],
    ['a nested array item', [[]], /index 0: expected an object, found an array/],
    ['a missing id', [{ ...makeTodo(), id: undefined }], /"id" must be a positive integer/],
    ['a string id', [makeTodo({ id: '1' })], /"id" must be a positive integer, found "1"/],
    ['a zero id', [makeTodo({ id: 0 })], /"id" must be a positive integer/],
    ['a fractional id', [makeTodo({ id: 1.5 })], /"id" must be a positive integer/],
    ['a non-string text', [makeTodo({ text: null })], /"text" must be a string, found null/],
    ['a non-boolean completed', [makeTodo({ completed: 'yes' })], /"completed" must be a boolean/],
    ['an unparseable createdAt', [makeTodo({ createdAt: 'yesterday' })], /"createdAt" must be an ISO 8601 timestamp/],
    ['a duplicate id', [makeTodo({ id: 1 }), makeTodo({ id: 1 })], /more than one todo with id 1/],
  ]) {
    it(`rejects ${label}`, () => {
      assert.throws(() => validateTodos(data, 'todos.json'), { name: 'StorageError', message });
    });
  }

  it('reports the index of the first bad item', () => {
    assert.throws(
      () => validateTodos([makeTodo({ id: 1 }), makeTodo({ id: 2 }), { id: 3 }], 'todos.json'),
      { message: /index 2/ },
    );
  });
});

