import assert from 'node:assert/strict';
import fs from 'node:fs';
import { describe, it } from 'node:test';
import { EXIT_SUCCESS, USAGE } from '../src/cli.js';
import { EXIT_FAILURE, EXIT_USAGE } from '../src/errors.js';
import { EMPTY_LIST_MESSAGE } from '../src/format.js';
import { makeTodo, readTodos, runInProcess, tempDir, todosPath, writeTodos } from './helpers/cli.js';

const FIXED_NOW = () => new Date('2026-09-30T12:34:56.789Z');

describe('run: help and dispatch', () => {
  it('prints usage to stderr and exits 2 with no command', () => {
    const result = runInProcess([], { cwd: '/nonexistent' });
    assert.equal(result.code, EXIT_USAGE);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, `${USAGE}\n`);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage to stdout and exits 0 for "${flag}"`, () => {
      const result = runInProcess([flag], { cwd: '/nonexistent' });
      assert.equal(result.code, EXIT_SUCCESS);
      assert.equal(result.stdout, `${USAGE}\n`);
      assert.equal(result.stderr, '');
    });
  }

  for (const command of ['frob', 'ADD', '__proto__', 'toString', 'constructor', '']) {
    it(`rejects unknown command ${JSON.stringify(command)} with usage`, (t) => {
      const dir = tempDir(t);
      const result = runInProcess([command], { cwd: dir });
      assert.equal(result.code, EXIT_USAGE);
      assert.ok(result.stderr.startsWith(`Error: Unknown command "${command}".`));
      assert.ok(result.stderr.includes(USAGE));
      assert.equal(fs.existsSync(todosPath(dir)), false);
    });
  }
});

describe('run: add', () => {
  it('adds a todo, stamps createdAt from the clock, and reports the id', (t) => {
    const dir = tempDir(t);
    const result = runInProcess(['add', 'Buy groceries'], { cwd: dir, now: FIXED_NOW });
    assert.equal(result.code, EXIT_SUCCESS);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');
    assert.deepEqual(readTodos(dir), [
      { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-09-30T12:34:56.789Z' },
    ]);
  });

  it('joins unquoted words into one todo', (t) => {
    const dir = tempDir(t);
    const result = runInProcess(['add', 'Walk', 'the', 'dog'], { cwd: dir });
    assert.equal(result.stdout, 'Added todo #1: Walk the dog\n');
    assert.equal(readTodos(dir)[0].text, 'Walk the dog');
  });

  it('exits 2 with a usage hint when text is missing', (t) => {
    const dir = tempDir(t);
    const result = runInProcess(['add'], { cwd: dir });
    assert.equal(result.code, EXIT_USAGE);
    assert.equal(result.stderr, 'Error: Missing todo text. Usage: node index.js add "<text>"\n');
    assert.equal(fs.existsSync(todosPath(dir)), false);
  });

  it('exits 2 when text is only whitespace', (t) => {
    const dir = tempDir(t);
    const result = runInProcess(['add', '   '], { cwd: dir });
    assert.equal(result.code, EXIT_USAGE);
    assert.match(result.stderr, /cannot be empty/);
    assert.equal(fs.existsSync(todosPath(dir)), false);
  });
});

describe('run: list', () => {
  it('prints the empty-list message when there are no todos', (t) => {
    const result = runInProcess(['list'], { cwd: tempDir(t) });
    assert.equal(result.code, EXIT_SUCCESS);
    assert.equal(result.stdout, `${EMPTY_LIST_MESSAGE}\n`);
  });

  it('prints each todo with its status indicator', (t) => {
    const dir = tempDir(t);
    writeTodos(dir, [makeTodo({ id: 1, text: 'Done thing', completed: true }), makeTodo({ id: 2, text: 'Open thing' })]);
    const result = runInProcess(['list'], { cwd: dir });
    assert.equal(result.stdout, '1. [x] Done thing\n2. [ ] Open thing\n\n2 todos: 1 pending, 1 done\n');
  });

  it('exits 2 when given extra arguments', (t) => {
    const result = runInProcess(['list', 'extra'], { cwd: tempDir(t) });
    assert.equal(result.code, EXIT_USAGE);
    assert.equal(result.stderr, 'Error: "list" takes no arguments, got 1.\n');
  });
});

for (const command of ['complete', 'delete']) {
  describe(`run: ${command} argument errors`, () => {
    it('exits 2 when the id is missing', (t) => {
      const result = runInProcess([command], { cwd: tempDir(t) });
      assert.equal(result.code, EXIT_USAGE);
      assert.equal(result.stderr, `Error: Missing todo id. Usage: node index.js ${command} <id>\n`);
    });

    it('exits 2 for a non-numeric id', (t) => {
      const result = runInProcess([command, 'abc'], { cwd: tempDir(t) });
      assert.equal(result.code, EXIT_USAGE);
      assert.equal(result.stderr, 'Error: Invalid todo id "abc". Expected a positive integer such as 1.\n');
    });

    it('exits 2 when given more than one id', (t) => {
      const dir = tempDir(t);
      writeTodos(dir, [makeTodo({ id: 1 }), makeTodo({ id: 2 })]);
      const result = runInProcess([command, '1', '2'], { cwd: dir });
      assert.equal(result.code, EXIT_USAGE);
      assert.equal(result.stderr, `Error: "${command}" takes exactly one id, got 2.\n`);
      assert.equal(readTodos(dir).length, 2);
    });

    it('exits 1 for an id that does not exist', (t) => {
      const dir = tempDir(t);
      writeTodos(dir, [makeTodo({ id: 1 })]);
      const result = runInProcess([command, '5'], { cwd: dir });
      assert.equal(result.code, EXIT_FAILURE);
      assert.equal(result.stderr, 'Error: Todo #5 not found. Run "node index.js list" to see existing ids.\n');
      assert.deepEqual(readTodos(dir), [makeTodo({ id: 1 })]);
    });

    it('exits 1 when there are no todos at all', (t) => {
      const dir = tempDir(t);
      const result = runInProcess([command, '1'], { cwd: dir });
      assert.equal(result.code, EXIT_FAILURE);
      assert.match(result.stderr, /Todo #1 not found/);
      assert.equal(fs.existsSync(todosPath(dir)), false);
    });
  });
}

describe('run: complete', () => {
  it('marks the todo done', (t) => {
