import assert from 'node:assert/strict';
import fs from 'node:fs';
import { describe, it } from 'node:test';
import { MAX_TEXT_LENGTH } from '../src/todos.js';
import {
  makeTodo,
  readTodos,
  runCli,
  runCliAsync,
  runInProcess,
  tempDir,
  todosPath,
  writeTodos,
  writeTodosRaw,
} from './helpers/cli.js';

describe('corrupted todos.json', () => {
  const corruptions = [
    ['truncated JSON', '[{"id": 1, "text": "Buy', /is not valid JSON/],
    ['plain text', 'hello world', /is not valid JSON/],
    ['an object instead of an array', '{"todos": []}', /must contain a JSON array of todos/],
    ['a todo missing its text', '[{"id": 1, "completed": false, "createdAt": "2026-01-01T00:00:00Z"}]', /"text" must be a string/],
    ['duplicate ids', JSON.stringify([makeTodo({ id: 1 }), makeTodo({ id: 1 })]), /more than one todo with id 1/],
  ];

  for (const [label, contents, message] of corruptions) {
    for (const args of [['list'], ['add', 'New'], ['complete', '1'], ['delete', '1']]) {
      it(`"${args[0]}" exits 1 and leaves the file untouched for ${label}`, (t) => {
        const cwd = tempDir(t);
        writeTodosRaw(cwd, contents);
        const result = runCli(args, { cwd });
        assert.equal(result.code, 1);
        assert.equal(result.stdout, '');
        assert.match(result.stderr, /^Error: .*todos\.json/);
        assert.match(result.stderr, message);
        assert.equal(fs.readFileSync(todosPath(cwd), 'utf8'), contents, 'corrupted data must not be overwritten');
        assert.deepEqual(fs.readdirSync(cwd), ['todos.json'], 'no lock or temp files left behind');
      });
    }
  }

  it('treats an empty file as an empty list and can add to it', (t) => {
    const cwd = tempDir(t);
    writeTodosRaw(cwd, '');
    assert.match(runCli(['list'], { cwd }).stdout, /^No todos yet\./);
    assert.equal(runCli(['add', 'First'], { cwd }).stdout, 'Added todo #1: First\n');
    assert.deepEqual(readTodos(cwd).map((todo) => todo.id), [1]);
  });

  it('accepts a hand-edited file whose ids are out of order', (t) => {
    const cwd = tempDir(t);
    writeTodos(cwd, [makeTodo({ id: 7 }), makeTodo({ id: 2 })]);
    assert.equal(runCli(['add', 'Next'], { cwd }).stdout, 'Added todo #8: Next\n');
  });
});

describe('id assignment', () => {
  it('does not fill gaps left by deleted todos', (t) => {
    const cwd = tempDir(t);
    for (const text of ['one', 'two', 'three']) runInProcess(['add', text], { cwd });
    runInProcess(['delete', '2'], { cwd });
    assert.equal(runInProcess(['add', 'four'], { cwd }).stdout, 'Added todo #4: four\n');
    assert.deepEqual(readTodos(cwd).map((todo) => todo.id), [1, 3, 4]);
  });

  it('accepts leading zeros in an id argument', (t) => {
    const cwd = tempDir(t);
    runInProcess(['add', 'one'], { cwd });
    assert.equal(runInProcess(['complete', '001'], { cwd }).stdout, 'Completed todo #1: one\n');
  });

  it('reports not-found rather than invalid for the largest safe integer id', (t) => {
    const result = runInProcess(['delete', String(Number.MAX_SAFE_INTEGER)], { cwd: tempDir(t) });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /not found/);
  });

  for (const id of ['0', '1.0', '9007199254740993', '#1', ' 1']) {
    it(`rejects id ${JSON.stringify(id)} as invalid`, (t) => {
      const result = runInProcess(['complete', id], { cwd: tempDir(t) });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /Invalid todo id/);
    });
  }
});

describe('todo text boundaries', () => {
  it('stores and lists unicode text (accents, CJK, RTL, emoji) unchanged', (t) => {
    const cwd = tempDir(t);
    const texts = ['Café crème', '買い物に行く', 'שלום עולם', 'Ship it 🚀👩‍💻'];
    for (const text of texts) runCli(['add', text], { cwd });
    assert.deepEqual(readTodos(cwd).map((todo) => todo.text), texts);
    const listed = runCli(['list'], { cwd }).stdout;
    texts.forEach((text, index) => assert.ok(listed.includes(`${index + 1}. [ ] ${text}\n`)));
  });

  it(`accepts text of exactly ${MAX_TEXT_LENGTH} characters through the CLI`, (t) => {
    const cwd = tempDir(t);
    const result = runCli(['add', 'x'.repeat(MAX_TEXT_LENGTH)], { cwd });
    assert.equal(result.code, 0);
    assert.equal(readTodos(cwd)[0].text.length, MAX_TEXT_LENGTH);
  });

  it(`rejects text of ${MAX_TEXT_LENGTH + 1} characters without creating the file`, (t) => {
    const cwd = tempDir(t);
    const result = runCli(['add', 'x'.repeat(MAX_TEXT_LENGTH + 1)], { cwd });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /maximum is 500/);
    assert.equal(fs.existsSync(todosPath(cwd)), false);
  });

  it('rejects multi-line text', (t) => {
    const cwd = tempDir(t);
    const result = runCli(['add', 'line one\nline two'], { cwd });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /single line/);
  });

  it('stores text that looks like a flag or JSON literally', (t) => {
    const cwd = tempDir(t);
    runCli(['add', '--help'], { cwd });
    runCli(['add', '"quoted" {"json": true} \\ backslash'], { cwd });
    assert.deepEqual(readTodos(cwd).map((todo) => todo.text), ['--help', '"quoted" {"json": true} \\ backslash']);
  });
});

describe('concurrent access and locking', () => {
  it('keeps every todo when many add commands run in parallel', async (t) => {
    const cwd = tempDir(t);
    const count = 12;
    const results = await Promise.all(
      Array.from({ length: count }, (_, i) => runCliAsync(['add', `Task ${i}`], { cwd })),
    );
    for (const result of results) assert.equal(result.code, 0, result.stderr);

    const todos = readTodos(cwd);
    assert.equal(todos.length, count, 'no concurrent add was lost');
    assert.deepEqual(todos.map((todo) => todo.id).sort((a, b) => a - b), Array.from({ length: count }, (_, i) => i + 1));
    assert.deepEqual(new Set(todos.map((todo) => todo.text)), new Set(results.map((_, i) => `Task ${i}`)));
    assert.deepEqual(fs.readdirSync(cwd), ['todos.json'], 'no lock or temp files left behind');
  });

  it('applies simultaneous complete and delete commands on different todos', async (t) => {
    const cwd = tempDir(t);
    writeTodos(cwd, Array.from({ length: 6 }, (_, i) => makeTodo({ id: i + 1, text: `Task ${i + 1}` })));
    const results = await Promise.all([
      runCliAsync(['complete', '1'], { cwd }),
      runCliAsync(['complete', '2'], { cwd }),
      runCliAsync(['delete', '3'], { cwd }),
      runCliAsync(['delete', '4'], { cwd }),
      runCliAsync(['add', 'Task 7'], { cwd }),
    ]);
    for (const result of results) assert.equal(result.code, 0, result.stderr);

    const byId = Object.fromEntries(readTodos(cwd).map((todo) => [todo.id, todo]));
    assert.deepEqual(Object.keys(byId).map(Number), [1, 2, 5, 6, 7]);
    assert.equal(byId[1].completed, true);
    assert.equal(byId[2].completed, true);
    assert.equal(byId[5].completed, false);
  });

  it('lets exactly one of two parallel deletes of the same id succeed', async (t) => {
    const cwd = tempDir(t);
    writeTodos(cwd, [makeTodo({ id: 1 })]);
    const results = await Promise.all([runCliAsync(['delete', '1'], { cwd }), runCliAsync(['delete', '1'], { cwd })]);
    assert.deepEqual(results.map((result) => result.code).sort(), [0, 1]);
    assert.deepEqual(readTodos(cwd), []);
  });

  it('fails with a clear message when another process holds the lock too long', (t) => {
    const cwd = tempDir(t);
    fs.writeFileSync(`${todosPath(cwd)}.lock`, '12345');
    const result = runInProcess(['add', 'Blocked'], { cwd, lock: { timeoutMs: 50, retryMs: 5 } });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /Timed out after 50ms waiting for .*todos\.json\.lock/);
    assert.equal(fs.existsSync(todosPath(cwd)), false);
  });

  it('recovers from a stale lock left by a crashed process', (t) => {
    const cwd = tempDir(t);
    const lockPath = `${todosPath(cwd)}.lock`;
    fs.writeFileSync(lockPath, '12345');
    const old = new Date(Date.now() - 60_000);
    fs.utimesSync(lockPath, old, old);
    const result = runCli(['add', 'After crash'], { cwd });
    assert.equal(result.code, 0, result.stderr);
    assert.equal(fs.existsSync(lockPath), false);
    assert.equal(readTodos(cwd)[0].text, 'After crash');
  });

  it('list does not wait for the lock', (t) => {
    const cwd = tempDir(t);
    writeTodos(cwd, [makeTodo()]);
    fs.writeFileSync(`${todosPath(cwd)}.lock`, '12345');
    const result = runInProcess(['list'], { cwd, lock: { timeoutMs: 50 } });
    assert.equal(result.code, 0);
    assert.match(result.stdout, /1\. \[ \] Buy groceries/);
  });
});

describe('file system failures', () => {
  const isRoot = typeof process.getuid === 'function' && process.getuid() === 0;

  it('exits 1 with a storage error when the directory is read-only', { skip: isRoot && 'root ignores permissions' }, (t) => {
    const cwd = tempDir(t);
    writeTodos(cwd, [makeTodo()]);
    fs.chmodSync(cwd, 0o555);
    t.after(() => fs.chmodSync(cwd, 0o755));

    const result = runCli(['add', 'Cannot save'], { cwd });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Could not create lock file .*todos\.json\.lock/);
    assert.equal(runCli(['list'], { cwd }).code, 0, 'reading still works');
  });

  it('exits 1 when todos.json is a directory', (t) => {
    const cwd = tempDir(t);
    fs.mkdirSync(todosPath(cwd));
    const result = runCli(['list'], { cwd });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Could not read .*todos\.json/);
  });
});

