    ['plain text', 'hello world', /is not valid JSON/],
    ['an object instead of an array', '{"todos": []}', /must contain a JSON array of todos/],
    ['a todo missing its text', '[{"id": 1, "completed": false, "createdAt": "2026-01-01T00:00:00Z"}]', /"text" must be a string/],
    ['duplicate ids', JSON.stringify([makeTodo({ id: 1 }), makeTodo({ id: 1 })]), /more than one todo with id 1/],
  ];

  for (const [label, contents, message] of corruptions) {
    for (const args of [['list'], ['add', 'New'], ['complete', '1'], ['delete', '1']]) {
      it(`"${args[0]}" exits 1 and leaves the file untouched for ${label}`, (t) => {
        const cwd = tempDir(t);
        writeTodosRaw(cwd, contents);
        const result = runCli(args, { cwd });
        assert.equal(result.code, 1);
        assert.equal(result.stdout, '');
